  "plan.det.fam.general": "Algemeen",
  "plan.det.fam.slabs": "Vloeren",
  "plan.det.fam.beams": "Liggers",
  "plan.det.fam.columns": "Kolommen",
  "plan.det.fam.joints": "Ligger-kolomverbindingen",
  "plan.det.fam.foundations": "Funderingen",
